import re

GERMAN_MAPPING = {
 'ae': 'ä', 'Ae': 'Ä', 'AE': 'Ä',
 'oe': 'ö', 'Oe': 'Ö', 'OE': 'Ö',
 'ue': 'ü', 'Ue': 'Ü', 'UE': 'Ü',
 'ss': 'ß', 'SS': 'ẞ',
}

GERMAN_BLOCKLIST = {
 "Koeffizienten":"Koeffizienten",
 "Bauer":"Bauer",
 "Mauer":"Mauer",
}

def german_word_convert(word, naive, prefer_original):
    def naive_replace(s):
        i=0
        res=""
        while i < len(s):
            matched=False
            for k in sorted(GERMAN_MAPPING.keys(), key=lambda x: -len(x)):
                if s[i:i+len(k)] == k:
                    res+=GERMAN_MAPPING[k]
                    i+=len(k)
                    matched=True
                    break
            if not matched:
                res+=s[i]
                i+=1
        return res
    naive_result = naive_replace(word)
    if naive:
        return naive_result
    if naive_result == word:
        return word
    if word in GERMAN_BLOCKLIST:
        return word
    known_valid_original = {"Masse","Busse","Strasse","Muenchen","Haende","Koeln","Bruecken","Muetter","Vaeter","Brueder","Aussicht","Ausser","Aussen","Fuss","Grosser","Scheisse","Koeffizienten","Bauer","Mauer"}
