    if word in known_valid_original and naive_result in known_valid_converted:
        if prefer_original:
            return word
        else:
            return naive_result
    return naive_result

def german_transform(text, naive=False, prefer_original=False):
    def repl_match(m):
        word=m.group(0)
        if re.search(r'(ae|oe|ue|ss|AE|Ae|OE|Oe|UE|Ue)', word):
            return german_word_convert(word, naive, prefer_original)
        else:
            return word
    return re.sub(r'[A-Za-zÄÖÜäöüß]+', repl_match, text)

