 ("Muesse", "Müsse", None),
 ("Haende", "Hände", None),
 ("Muenchen", "München", None),
]
for w, exp, flag in tests:
    out=german_transform(w)
    print(w, out, exp, out==exp)
    if flag=="prefer":
        print("prefer", german_transform(w,prefer_original=True))
    # naive
    print("naive", german_transform(w,naive=True))

# Test sentence
